/**
 * SIGNAL service worker — offline support for a mobile-first game.
 *
 * Every asset the game needs is now same-origin (fonts were self-hosted in an
 * earlier pass), so offline play is essentially free. The only network the game
 * genuinely needs is the leaderboard, which already degrades gracefully.
 *
 * Deliberately hand-written rather than generated by a build plugin: the whole
 * strategy is ~40 lines of policy, and hashed filenames mean there is no
 * precache manifest to keep in sync.
 *
 * Strategy:
 *  - Navigations: network-first, cached under their own URL, falling back to
 *    that URL and only then to the shell. A player with a connection always
 *    gets the current build; a player without one still gets in.
 *    Note the per-URL keying: the shell slot is only ever written from a real
 *    shell navigation. Writing every navigation into it meant a visit to
 *    /privacy.html became the offline response for the game itself.
 *  - /assets/* (content-hashed by Vite): cache-first. The hash IS the version,
 *    so a cached hit can never be stale.
 *  - Fonts and icons: cache-first, same reasoning — they change by filename.
 *  - Everything cross-origin (Supabase): not touched. Leaderboard reads and
 *    writes must never be served from cache; a stale board is worse than none,
 *    and score submissions must not be replayed.
 */

// v2: v1 could have stored a non-shell page in the SHELL slot (see the
// navigation handler), and the activate step drops old caches, so the bump is
// what actually clears a poisoned entry from an already-installed client.
// v3: adds /terms.html to PRECACHE. Without a bump, an already-installed client
// keeps its v2 cache and never fetches the new page, so the terms would be
// missing offline for exactly the returning players most likely to look.
const CACHE_VERSION = 'signal-v3';
const SHELL = '/index.html';

// Kept small on purpose: only what's needed to boot offline. Hashed JS is
// picked up at runtime on first load instead of being listed here.
const PRECACHE = [
  '/',
  '/index.html',
  // Precached because a policy that is only reachable online is not reachable at
  // the moment an offline player goes looking for it.
  '/privacy.html',
  '/terms.html',
  '/manifest.webmanifest',
  '/favicon.svg',
  '/icon-192.png',
  '/icon-512.png',
  '/fonts/sora.woff2',
  '/fonts/jetbrains-mono.woff2',
  '/fonts/inter.woff2',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_VERSION)
      // Individually, so one 404 can't fail the whole install the way
      // cache.addAll() would.
      .then((cache) => Promise.all(
        PRECACHE.map((url) => cache.add(url).catch(() => undefined)),
      ))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(
        keys.filter((k) => k !== CACHE_VERSION).map((k) => caches.delete(k)),
      ))
      .then(() => self.clients.claim()),
  );
});

function isCacheableAsset(url) {
  return url.pathname.startsWith('/assets/')
      || url.pathname.startsWith('/fonts/')
      || url.pathname.startsWith('/icon-')
      || url.pathname === '/favicon.svg'
      || url.pathname === '/manifest.webmanifest';
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;

  const url = new URL(req.url);
  // Cross-origin (Supabase, telemetry) goes straight to the network, always.
  if (url.origin !== self.location.origin) return;

  if (req.mode === 'navigate') {
    event.respondWith(
      fetch(req)
        .then((res) => {
          if (res && res.status === 200 && res.type === 'basic') {
            // Keyed by request, so /privacy.html refreshes /privacy.html.
            const perUrl = res.clone();
            caches.open(CACHE_VERSION).then((c) => c.put(req, perUrl)).catch(() => {});
            // The shell slot is written only by an actual shell navigation.
            if (url.pathname === '/' || url.pathname === SHELL) {
              const forShell = res.clone();
              caches.open(CACHE_VERSION).then((c) => c.put(SHELL, forShell)).catch(() => {});
            }
          }
          return res;
        })
        // Offline: prefer the page actually asked for, and only fall back to the
        // shell so a deep link still lands somewhere playable.
        .catch(() => caches.match(req)
          .then((hit) => hit || caches.match(SHELL))
          .then((hit) => hit || caches.match('/'))),
    );
    return;
  }

  if (!isCacheableAsset(url)) return;

  event.respondWith(
    caches.match(req).then((hit) => {
      if (hit) return hit;
      return fetch(req).then((res) => {
        // Only cache real successes; an opaque or errored response cached here
        // would be served back indefinitely.
        if (res && res.status === 200 && res.type === 'basic') {
          const copy = res.clone();
          caches.open(CACHE_VERSION).then((c) => c.put(req, copy)).catch(() => {});
        }
        return res;
      });
    }),
  );
});
